// === Tab: mySketch ===
var seed = "openprocessing";
var nums;
var maxLife = 35;
var noiseScale = 500;
var simulationSpeed = 0.9;
var fadeFrame = 0;
var padding_top = 100;
var padding_side = 100;
var inner_square = 512;

var particles = [];
var backgroundColor;

var mode = 0; // 0 = lineal, 1 = expansivo
var collisionDistance = 18;

function setup() {
  createCanvas(windowHeight, windowHeight);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  resetSketch();
}

function resetSketch() {
  randomSeed(seed + frameCount);
  noiseSeed(frameCount + 99);

  nums = 140;
  backgroundColor = color(8, 8, 8);

  background(backgroundColor);
  noFill();
  smooth();

  padding_top = (height - inner_square) / 2;
  padding_side = (width - inner_square) / 12;

  mode = (mode + 1) % 2;

  particles = [];
  for (var i = 0; i < nums; i++) {
    var p = new Particle();
    p.respawnTop();
    particles[i] = p;
  }
}

function draw() {
  ++fadeFrame;

  if (fadeFrame % 4 == 0) {
    blendMode(BLEND);
    noStroke();
    fill(8, 8, 8, 18);
    rect(0, 0, width, height);
  }

  detectCollisions();

  blendMode(ADD);
  for (var i = 0; i < nums; i++) {
    var iterations = int(map(i, 0, nums, 6, 2));
    particles[i].move(iterations);
    particles[i].checkEdge();
    particles[i].display();
  }
}

function detectCollisions() {
  for (var i = 0; i < nums; i++) {
    particles[i].colliding = false;
  }

  for (var i = 0; i < nums; i++) {
    for (var j = i + 1; j < nums; j++) {
      var d = dist(
        particles[i].pos.x, particles[i].pos.y,
        particles[j].pos.x, particles[j].pos.y
      );

      if (d < collisionDistance) {
        particles[i].colliding = true;
        particles[j].colliding = true;

        particles[i].collisionFlash = 18;
        particles[j].collisionFlash = 18;
      }
    }
  }
}

function keyReleased() {
  if (key == 'r' || key == 'R' || keyCode == 32) {
    resetSketch();
  }

  if (key == 's' || key == 'S') {
    save("gray_red_lines_" + frameCount + ".jpg");
  }
}

function Particle() {
  this.pos = createVector(random(0, width), random(0, height));
  this.prev = this.pos.copy();
  this.vel = createVector(0, 0);
  this.life = random(0, maxLife);

  this.center = createVector(width / 2, height / 2);
  this.angleOffset = random(TWO_PI);
  this.radialSpeed = random(0.3, 2.2);
  this.swirl = random(-0.35, 0.35);

  // velocidades distintas: unas lentas y otras rápidas
  if (random() < 0.5) {
    this.speedFactor = random(0.35, 0.8);   // lentas
  } else {
    this.speedFactor = random(1.2, 2.8);    // rápidas
  }

  // grosor variable
  this.weight = random(0.3, 2.2);

  // paleta base en plomos
  this.gray1 = random(90, 170);
  this.gray2 = random(160, 230);

  // estado de colisión
  this.colliding = false;
  this.collisionFlash = 0;

  this.move = function(iterations) {
    if ((this.life -= 0.01666) < 0) {
      this.respawnTop();
    }

    while (iterations > 0) {
      this.prev = this.pos.copy();

      if (mode === 0) {
        // MODO LINEAL / FLUIDO
        var transition = map(this.pos.x, padding_side, width - padding_side, 0, 1, true);
        var angle = noise(this.pos.x / noiseScale, this.pos.y / noiseScale) * transition * TWO_PI * 3.0;

        this.vel.x = cos(angle);
        this.vel.y = sin(angle);

        var speedVariation = map(
          noise(this.pos.x * 0.003, this.pos.y * 0.003, frameCount * 0.01),
          0, 1, 0.7, 1.6
        );

        this.vel.mult(simulationSpeed * this.speedFactor * speedVariation);
        this.pos.add(this.vel);

      } else {
        // MODO EXPANSIVO
        var dir = p5.Vector.sub(this.pos, this.center);

        if (dir.mag() < 1) {
          dir = p5.Vector.fromAngle(this.angleOffset);
        }

        dir.normalize();

        var outward = dir.copy().mult(this.radialSpeed * this.speedFactor);
        var tangent = createVector(-dir.y, dir.x).mult(this.swirl);

        var n = noise(this.pos.x * 0.002, this.pos.y * 0.002, frameCount * 0.003);
        var extraAngle = map(n, 0, 1, -0.4, 0.4);

        outward.rotate(extraAngle);

        this.vel = outward.add(tangent);
        this.pos.add(this.vel);

        this.radialSpeed *= 1.0015;
      }

      --iterations;
    }

    if (this.collisionFlash > 0) {
      this.collisionFlash--;
    }
  };

  this.checkEdge = function() {
    if (
      this.pos.x > width - padding_side ||
      this.pos.x < padding_side ||
      this.pos.y > height - padding_top ||
      this.pos.y < padding_top
    ) {
      this.respawnTop();
    }
  };

  this.respawnTop = function() {
    if (mode === 0) {
      this.pos.x = random(padding_side, width - padding_side);
      this.pos.y = padding_top;
    } else {
      var r = random(5, 40);
      var a = random(TWO_PI);
      this.pos.x = width / 2 + cos(a) * r;
      this.pos.y = height / 2 + sin(a) * r;
    }

    this.prev = this.pos.copy();
    this.life = maxLife;

    if (random() < 0.5) {
      this.speedFactor = random(0.35, 0.8);
    } else {
      this.speedFactor = random(1.2, 2.8);
    }

    this.weight = random(0.3, 2.2);
    this.gray1 = random(90, 170);
    this.gray2 = random(160, 230);

    this.radialSpeed = random(0.3, 2.2);
    this.swirl = random(-0.35, 0.35);

    this.colliding = false;
    this.collisionFlash = 0;
  };

  this.display = function() {
    var c;

    if (this.colliding || this.collisionFlash > 0) {
      // tonos rojos cuando chocan
      var redMix = map(this.collisionFlash, 0, 18, 0.35, 1);
      c = lerpColor(
        color(110, 20, 20, 80),
        color(255, random(40, 90), random(40, 70), 180),
        redMix
      );
    } else {
      // distintos plomos
      var t = map(this.speedFactor, 0.35, 2.8, 0, 1, true);
      c = lerpColor(
        color(this.gray1, this.gray1, this.gray1, 85),
        color(this.gray2, this.gray2, this.gray2, 170),
        t
      );
    }

    stroke(c);
    strokeWeight(this.weight);
    line(this.prev.x, this.prev.y, this.pos.x, this.pos.y);
  };
}

